export function getWilayaById(id) {
  const num = Number(id);
  return WILAYAS_69.find(w => w.id === num || Number(w.code) === num) || null;
}

export function getCommunesByWilaya(wilayaId) {
  const num = Number(wilayaId);
  return COMMUNES_ALL.filter(c => c.wilayaId === num);
}

export function getDairasByWilaya(wilayaId) {
  const num = Number(wilayaId);
  return DAIRAS_ALL.filter(d => d.wilayaId === num);
}

export function searchCommunes(query, limit = 15) {
  if (!query || typeof query !== 'string') return [];
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];

  const results = [];
  for (const c of COMMUNES_ALL) {
    const matchFr = c.nameFr && c.nameFr.toLowerCase().includes(q);
    const matchAr = c.nameAr && c.nameAr.includes(q);
    const matchDaira = (c.dairaFr && c.dairaFr.toLowerCase().includes(q)) || (c.dairaAr && c.dairaAr.includes(q));
    const matchPost = c.postCode && c.postCode.includes(q);

    if (matchFr || matchAr || matchDaira || matchPost) {
      const wilaya = getWilayaById(c.wilayaId);
      results.push({
        ...c,
        wilayaCode: wilaya ? wilaya.code : String(c.wilayaId).padStart(2, '0'),
        wilayaNameFr: wilaya ? wilaya.nameFr : '',
        wilayaNameAr: wilaya ? wilaya.nameAr : '',
        agency: wilaya ? wilaya.agency : 'Yalidine Express',
        homePrice: wilaya ? wilaya.homePrice : 800,
        agencyPrice: wilaya ? wilaya.agencyPrice : 450
      });
      if (results.length >= limit) break;
    }
  }
  return results;
}

export function autoCompleteLocation(communeQuery) {
  const matches = searchCommunes(communeQuery, 1);
  return matches.length > 0 ? matches[0] : null;
}
